//! Parity and regression tests for the Sesame (CSM) TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_sesame/`, generated by
//! `tools/gen_sesame_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference module (its network tokenizer,
//! Mimi, and watermarker singletons patched for tiny seeded instances),
//! so the traces carry `_tokenize_audio` frame layouts, the greedy
//! `generate` loop frames, the `generate_result` chunked streaming
//! decode, and the sampler chain on raw logits.

use std::path::{Path, PathBuf};

use serde_json::Value;
use turbospark_model_io::safetensors::SafetensorsFile;

use super::{
    frames_to_codes, text_prompt_string, watermark, GenerateParams, Model, ModelConfig, Prompt,
    StopReason, DEFAULT_SAMPLE_RATE, MIMI_REPO, TOKENIZER_REPO,
};
use crate::codec::mimi::{Mimi, MimiConfig};

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_sesame")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn i32_rows(value: &Value) -> Vec<Vec<i32>> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .map(i32_vec)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Filtered sampler outputs use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn bool_vec(value: &Value) -> Vec<bool> {
    value
        .as_array()
        .expect("mask")
        .iter()
        .map(|v| v.as_bool().expect("mask entry"))
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences against the fixture traces when the
/// gates were frozen; assertions use these values, not re-measured ones.
/// The Mimi decode parity (full batch decode versus the reference chunked
/// streaming decoder) measured 2.7e-7 and the end-to-end generate
/// waveform 2.7e-7 (conv accumulation order); the sampler stages are
/// bit-exact, so the gate sits well above the measurements.
const WAVEFORM_TOLERANCE: f32 = 2e-6;

fn decode_mimi() -> Mimi {
    let config_value = read_json(&testdata("decode/config.json"));
    let config = MimiConfig::from_json(&config_value).expect("mimi config");
    let file = SafetensorsFile::open(&testdata("decode/model.safetensors")).expect("weights open");
    Mimi::load(config, &file).expect("tiny mimi loads")
}

fn generate_model(name: &str) -> Model {
    Model::open(&testdata(name)).expect("family model loads")
}

fn greedy_params() -> GenerateParams {
    GenerateParams {
        temperature: 0.0,
        top_p: 0.0,
        min_p: 0.0,
        top_k: 50,
        max_audio_length_ms: 320.0,
    }
}

fn prompt_from_traces(traces: &Value, model: &Model) -> Prompt {
    let text_ids = i32_vec(&traces["text_ids"]);
    let prompt = model.tokenize_text_segment(&text_ids);
    assert_eq!(prompt.tokens, i32_vec(&traces["prompt_frames"]));
    assert_eq!(prompt.mask, bool_vec(&traces["prompt_frame_mask"]));
    prompt
}

#[test]
fn tokenize_audio_matches_the_reference_frame_layouts() {
    let traces = read_json(&testdata("decode/traces.json"));
    let mimi = decode_mimi();
    let wave = f32_vec(&traces["wave"]);
    let codes = super::encode_audio(&mimi, &wave).expect("encodes");
    assert_eq!(codes, i32_rows(&traces["encode_codes"]), "encode codes");
    let model = generate_model("generate");
    let prompt = model.tokenize_audio(&codes, false).expect("frames");
    assert_eq!(prompt.tokens, i32_vec(&traces["audio_frames"]));
    assert_eq!(prompt.mask, bool_vec(&traces["audio_frame_mask"]));
    let eos_prompt = model.tokenize_audio(&codes, true).expect("frames");
    assert_eq!(eos_prompt.tokens, i32_vec(&traces["audio_frames_eos"]));
    assert_eq!(eos_prompt.mask, bool_vec(&traces["audio_frame_mask_eos"]));
    // The eos variant appends exactly one all-zero frame row.
    assert_eq!(eos_prompt.rows, prompt.rows + 1);
}

#[test]
fn tokenize_audio_refuses_a_codebook_count_mismatch() {
    let model = generate_model("generate");
    let error = model
        .tokenize_audio(&[vec![1, 2], vec![3, 4]], false)
        .unwrap_err();
    assert!(error.to_string().contains("codebooks"), "{error}");
}

#[test]
fn decode_matches_the_reference_chunked_streaming_decode() {
    let traces = read_json(&testdata("decode/traces.json"));
    let frames = i32_rows(&traces["long_frames"]);
    assert_eq!(frames.len(), 63, "the second chunk rides the 62-frame cap");
    let mimi = decode_mimi();
    let codes = frames_to_codes(&frames, 4);
    let got = mimi.decode(&codes).expect("decodes");
    let want = f32_vec(&traces["long_wave"]);
    assert_eq!(got.len(), want.len());
    let diff = max_abs_diff(&got, &want);
    assert!(diff <= WAVEFORM_TOLERANCE, "chunked decode diff {diff}");
}

#[test]
fn greedy_generation_matches_the_reference_frames_and_waveform() {
    let traces = read_json(&testdata("generate/traces.json"));
    let mimi = decode_mimi();
    // The prompt builder parity rides the same load.
    let prompt = prompt_from_traces(&traces, &generate_model("generate"));
    let mut model = generate_model("generate");
    let got = model
        .generate(&mimi, &prompt, &greedy_params(), 0)
        .expect("generate runs");
    assert_eq!(got.frames, i32_rows(&traces["frames"]), "generated frames");
    assert_eq!(got.stopped_by, StopReason::MaxFrames);
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(got.samples.len(), want_wave.len());
    let diff = max_abs_diff(&got.samples, &want_wave);
    assert!(diff <= WAVEFORM_TOLERANCE, "generate waveform diff {diff}");
    // The codebook-major codes are the frame transpose.
    assert_eq!(
        got.codes,
        frames_to_codes(&got.frames, model.config.audio_num_codebooks)
    );
}

#[test]
fn zeroed_codebook_heads_stop_on_an_all_zero_first_frame() {
    let traces = read_json(&testdata("generate_eos/traces.json"));
    let mut model = generate_model("generate_eos");
    let prompt = prompt_from_traces(&traces, &model);
    let mimi = decode_mimi();
    let got = model
        .generate(&mimi, &prompt, &greedy_params(), 0)
        .expect("generate runs");
    assert!(got.frames.is_empty(), "no frames survive the eos");
    assert_eq!(got.codes, Vec::<Vec<i32>>::new());
    assert!(got.samples.is_empty());
    assert_eq!(got.stopped_by, StopReason::AllZeroFrame);
}

#[test]
fn generate_refuses_an_oversize_prompt_or_an_empty_one() {
    let mut model = generate_model("generate");
    let mimi = decode_mimi();
    let error = model
        .generate(
            &mimi,
            &Prompt {
                tokens: Vec::new(),
                mask: Vec::new(),
                rows: 0,
                width: 5,
            },
            &greedy_params(),
            0,
        )
        .unwrap_err();
    assert!(error.to_string().contains("empty prompt"), "{error}");
    // max_seq_len = 2048 - 4 = 2044 for the fixture frame budget; 2044
    // rows is the first refused width.
    let rows = 2044;
    let oversized = Prompt {
        tokens: vec![0i32; rows * 5],
        mask: vec![false; rows * 5],
        rows,
        width: 5,
    };
    let error = model
        .generate(&mimi, &oversized, &greedy_params(), 0)
        .unwrap_err();
    assert!(error.to_string().contains("too long"), "{error}");
}

#[test]
fn sampling_filters_match_the_reference_on_raw_logits() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().expect("cases") {
        let logits = f32_vec(&case["logits"]);
        let want_argmax = case["argmax"].as_u64().expect("argmax") as usize;
        assert_eq!(
            crate::tts::sampling::argmax(&logits),
            want_argmax,
            "case {}",
            case["name"]
        );
        if let Some(top_k) = case["top_k_logprobs"].as_array() {
            let mut filtered = logits.clone();
            crate::tts::sampling::apply_top_k(
                &mut filtered,
                case["top_k"].as_u64().expect("top_k") as usize,
            )
            .unwrap();
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_k.clone())));
            assert!(diff == 0.0, "case {} top_k diff {diff}", case["name"]);
        }
        if let Some(top_p) = case["top_p_logprobs"].as_array() {
            let mut filtered = logits.clone();
            crate::tts::sampling::apply_top_p(
                &mut filtered,
                case["top_p"].as_f64().expect("top_p") as f32,
            );
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_p.clone())));
            assert!(diff == 0.0, "case {} top_p diff {diff}", case["name"]);
        }
    }
}

#[test]
fn flavor_presets_match_the_reference_args() {
    let traces = read_json(&testdata("flavors/traces.json"));
    for (flavor, args) in traces.as_object().expect("flavors") {
        let config = ModelConfig::from_json(&serde_json::json!({
            "text_vocab_size": 128256,
            "audio_vocab_size": 2048,
            "audio_num_codebooks": 32,
            "backbone_flavor": flavor,
            "decoder_flavor": flavor,
        }))
        .unwrap_or_else(|error| panic!("flavor {flavor} parse failed: {error}"));
        assert_eq!(config.backbone.num_hidden_layers, args["num_hidden_layers"]);
        assert_eq!(
            config.backbone.num_attention_heads,
            args["num_attention_heads"]
        );
        assert_eq!(
            config.backbone.num_key_value_heads,
            args["num_key_value_heads"]
        );
        assert_eq!(config.backbone.head_dim, args["head_dim"]);
        assert_eq!(config.backbone.hidden_size, args["hidden_size"]);
        assert_eq!(config.backbone.intermediate_size, args["intermediate_size"]);
        assert_eq!(config.backbone.rope_theta as f64, args["rope_theta"]);
        assert_eq!(config.decoder.num_hidden_layers, args["num_hidden_layers"]);
        assert_eq!(config.decoder.hidden_size, args["hidden_size"]);
        assert_eq!(config.decoder.head_dim, args["head_dim"]);
    }
}

#[test]
fn explicit_config_fields_and_defaults_match_the_reference() {
    let model = generate_model("generate");
    assert_eq!(model.config.text_vocab_size, 64);
    assert_eq!(model.config.audio_vocab_size, 16);
    assert_eq!(model.config.audio_num_codebooks, 4);
    assert_eq!(model.config.backbone.num_hidden_layers, 2);
    assert_eq!(model.config.decoder.num_hidden_layers, 1);
    assert!(model.config.speaker_prefix_space);
    // The flags the reference Model.__init__ reads default like the
    // reference config.get calls.
    let defaults = ModelConfig::from_json(&serde_json::json!({
        "text_vocab_size": 8,
        "audio_vocab_size": 8,
        "audio_num_codebooks": 2,
        "backbone_flavor": "llama-100M",
        "decoder_flavor": "llama-100M",
    }))
    .expect("flavor config parses");
    assert!(!defaults.speaker_prefix_space);
    assert!(defaults.use_default_voice_prompt);
    assert!(defaults.voice_match);
    assert_eq!(DEFAULT_SAMPLE_RATE, 24000);
    assert_eq!(MIMI_REPO, "kyutai/moshiko-pytorch-bf16");
    assert_eq!(TOKENIZER_REPO, "unsloth/Llama-3.2-1B");
}

#[test]
fn text_prompt_string_matches_the_reference_prefixes() {
    assert_eq!(text_prompt_string(0, "hi there", false), "[0]hi there");
    assert_eq!(text_prompt_string(1, "hi there", true), "[1] hi there");
    // The reference lstrips the prompt text only when the space is on.
    assert_eq!(text_prompt_string(0, "  hi", true), "[0] hi");
    assert_eq!(text_prompt_string(0, "  hi", false), "[0]  hi");
}

#[test]
fn watermark_stage_is_refused_with_a_descriptive_error() {
    let error = watermark(&[0.0; 8], DEFAULT_SAMPLE_RATE, &super::CSM_1B_GH_WATERMARK)
        .expect_err("watermark refuses");
    let message = error.to_string();
    assert!(message.contains("silentcipher"), "{message}");
    assert!(message.contains("watermark"), "{message}");
}
